"use client";

// Razorpay Checkout for UPI. The options (public key id, order id, amount, UPI-only method config) are
// generated by the backend; no secret ever reaches the browser. The callback is NOT proof of payment:
// it is forwarded to POST /payments/razorpay/verify and the order page shows whatever the server decides.

import { paymentApi } from "./api/endpoints";

const SRC = "https://checkout.razorpay.com/v1/checkout.js";
let loader = null;

export function loadRazorpay() {
  if (typeof window === "undefined") return Promise.reject(new Error("Not in a browser"));
  if (window.Razorpay) return Promise.resolve(window.Razorpay);
  loader ??= new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = SRC;
    s.async = true;
    s.onload = () => (window.Razorpay ? resolve(window.Razorpay) : reject(new Error("Payment library unavailable")));
    s.onerror = () => {
      loader = null;
      reject(new Error("Couldn't load the payment window. Check your connection and try again."));
    };
    document.head.appendChild(s);
  });
  return loader;
}

/**
 * Opens Razorpay and resolves with one of:
 *  { status: "verified", result }   — server verified (result.outcome: confirmed | duplicate | refunding | failed)
 *  { status: "verify_error", error } — callback received but verification request failed (server/webhook may still confirm)
 *  { status: "dismissed", lastError } — customer closed the window (lastError: last failed attempt, if any)
 * A failed attempt keeps the Razorpay window open so the customer can retry inside it; we only settle
 * on success or close.
 */
export async function payWithRazorpay(payment) {
  const Razorpay = await loadRazorpay();
  return new Promise((resolve) => {
    let settled = false;
    let lastError = null;
    const done = (v) => {
      if (!settled) {
        settled = true;
        resolve(v);
      }
    };
    const rzp = new Razorpay({
      ...payment.checkoutOptions,
      theme: { color: "#2d3527" },
      modal: { ondismiss: () => done({ status: "dismissed", lastError }), confirm_close: true },
      handler: async (resp) => {
        try {
          const r = await paymentApi.verify({ razorpay_order_id: resp.razorpay_order_id, razorpay_payment_id: resp.razorpay_payment_id, razorpay_signature: resp.razorpay_signature });
          done({ status: "verified", result: r.data });
        } catch (error) {
          done({ status: "verify_error", error });
        }
      },
    });
    rzp.on("payment.failed", (resp) => {
      lastError = { message: resp?.error?.description || "Payment failed" };
    });
    rzp.open();
  });
}
